void Solver::bump_var(int var, double coeff) {
    // Increment activity for the variable.
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Lazy overflow handling: rescale all activities if any exceeds the threshold.
    constexpr double OVERFLOW_THR = 1e100;
    constexpr double RESCALE_FAC   = 1e-100;
    if (activity[var] > OVERFLOW_THR || var_inc > OVERFLOW_THR) {
        for (int i = 1; i <= vars; ++i) activity[i] *= RESCALE_FAC;
        var_inc *= RESCALE_FAC;
    }

    // Keep the VSIDS priority queue up‑to‑date.
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
